(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.015-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.018+t*0.45)*8 + Math.sin((x+w1x)*0.012-t*0.35)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*60, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.05, 1.8, 1.3]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const df = Math.exp(-d*0.003);
    aS += Math.sin(d*f-t*sp)*w*df;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*df;
    aS2 += Math.sin(d*f*1.6-t*sp*1.3+0.8)*w*df*0.5;
    iS2 += Math.sin(d*f*1.1+t*sp*0.9+3.2)*w*df*0.5;
  }
  const act = aS/8, inh = iS/8, act2 = aS2/8, inh2 = iS2/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.08+ang*5-t*2.0)*0.15;
  const micro = (Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)+Math.sin((sx-sy)*0.2+t*0.8))*0.12;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2 = Math.tanh((act2-inh2*0.6+spiral2)*2.8);
  const cross = Math.sin(rd1*Math.PI)*Math.sin(rd2*Math.PI*1.5)*0.4;
  const reaction = Math.tanh((rd1*0.55+rd2*0.25+cross+cell*0.2+micro)*2.0);
  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.2:1.0;
  const lum = 0.82+Math.sin(reaction*Math.PI*1.2)*0.18;
  const v = reaction*0.5+0.5;
  const pal = [[6,12,52],[12,45,85],[18,90,115],[25,140,130],[60,170,120],
    [160,185,80],[210,180,60],[220,140,65],[195,90,70],[160,55,80],[100,30,70],[45,18,55],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
